INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('pot-roast', 'Perfect Sunday Pot Roast', 'A Dutch oven chuck roast with browned onions, carrots, red wine, beef stock, rosemary, and thyme. It cooks low and slow until the beef pulls apart with a fork.', 'Dinner', 'American comfort food', 'Easy', 'images/recipes/pot-roast-1200.webp', 'images/recipes/pot-roast-640.webp', 'Dutch oven pot roast with carrots and onions in braising liquid', 'Photo by Mark Miller, CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/Special:MediaSearch?search=American%20pot%20roast&type=image', 'Pot roast became a staple in American home cooking because tougher cuts of beef could be slowly braised until tender, creating a budget-friendly family meal.', 10, 'One 4 to 5 lb roast', 20, 240, 260, NULL, 275, '["Dutch oven","Make-ahead","Family dinner","Gluten free"]', '["Large Dutch oven","Tongs","Whisk or wooden spoon","Sharp knife"]', '[{"id":"i1","section":"Roast","name":"whole chuck roast","quantity":4.5,"unit":"lb","notes":"well marbled"},{"id":"i2","section":"Roast","name":"kosher salt","quantity":1,"unit":"to taste"},{"id":"i3","section":"Roast","name":"black pepper","quantity":1,"unit":"to taste"},{"id":"i4","section":"Roast","name":"olive oil","quantity":2,"unit":"tbsp","notes":"plus more if the pan dries out"},{"id":"i5","section":"Vegetables","name":"yellow onions","quantity":2,"unit":"whole","notes":"peeled and halved"},{"id":"i6","section":"Vegetables","name":"carrots","quantity":7,"unit":"whole","notes":"cut into 2-inch pieces"},{"id":"i7","section":"Braising liquid","name":"red wine","quantity":1,"unit":"cup","notes":"optional, or use beef stock"},{"id":"i8","section":"Braising liquid","name":"beef stock","quantity":2.5,"unit":"cups","notes":"enough to come halfway up the roast"},{"id":"i9","section":"Braising liquid","name":"fresh rosemary","quantity":3,"unit":"sprigs"},{"id":"i10","section":"Braising liquid","name":"fresh thyme","quantity":3,"unit":"sprigs"},{"id":"i11","section":"Braising liquid","name":"tomato paste","quantity":2,"unit":"tbsp","notes":"optional, for deeper flavor"}]', '[{"id":"s1","order":1,"instruction":"Heat the oven to 275°F. Pat the chuck roast dry, then season every side generously with kosher salt and black pepper."},{"id":"s2","order":2,"instruction":"Warm the olive oil in a large Dutch oven over medium-high heat. Brown the onion halves cut-side down, then transfer them to a plate."},{"id":"s3","order":3,"instruction":"Add the carrots to the hot pot and toss for about a minute, just until they pick up some color. Move them to the plate with the onions."},{"id":"s4","order":4,"instruction":"Add a little more oil if needed. Sear the roast for about a minute per side until it has a deep brown crust, then remove it to a plate."},{"id":"s5","order":5,"instruction":"Pour in the wine or 1 cup of beef stock and scrape the browned bits from the bottom of the pot. Whisk in tomato paste if using."},{"id":"s6","order":6,"instruction":"Return the roast to the pot. Add enough beef stock to come halfway up the meat, then nestle in the onions, carrots, rosemary, and thyme."},{"id":"s7","order":7,"instruction":"Cover the pot and roast until fork tender, about 3 hours for a 3 lb roast or 4 hours for a 4 to 5 lb roast."},{"id":"s8","order":8,"instruction":"Rest for 10 minutes. Slice or pull the beef apart, spoon over some braising liquid, and serve with the carrots and onions."}]', '["Choose a chuck roast with visible marbling; the fat and connective tissue make the roast tender.","Do not rush the sear. The browned crust and browned vegetables build the flavor of the braising liquid.","If you skip wine, use beef stock for the deglaze and add a splash of Worcestershire sauce if you want extra savoriness."]', '{"calories":359,"protein":"45 g","fat":"14 g","carbohydrates":"7 g"}', '[]', 'Try adding mushrooms, pearl onions, or baby potatoes during the last hour if you want a fuller one-pot dinner.', 'Store beef and vegetables in an airtight container with some braising liquid for up to 4 days in the refrigerator, or freeze up to 3 months.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('cows-in-a-blanket', 'Cows-in-a-Blanket', 'A quick party snack made with beef sticks wrapped in crescent dough, brushed with egg wash, and baked until golden.', 'Appetizer', 'Texas party food', 'Easy', 'images/recipes/cows-in-a-blanket-1200.webp', 'images/recipes/cows-in-a-blanket-640.webp', 'Beef sticks wrapped in golden crescent dough on a serving tray', 'Image via Beef Loving Texans', 'https://beeflovingtexans.com/recipe/cows-in-a-blanket/', 'This is a beef-forward spin on pigs in a blanket, built for game days, potlucks, and snack boards.', 5, '16 wrapped beef-stick bites', 15, 20, 35, NULL, 375, '["Appetizer","Quick & easy","Texas favorites","Party food"]', '["Large baking sheet","Parchment paper","Pastry brush","Small bowl"]', '[{"id":"ciab-i1","section":"Filling","name":"original beef sticks","quantity":8,"unit":"whole","notes":"4 oz total, halved crosswise"},{"id":"ciab-i2","section":"Dough","name":"refrigerated crescent roll dough","quantity":8,"unit":"oz tube"},{"id":"ciab-i3","section":"Dough","name":"Dijon, pepper jelly, BBQ sauce, or pesto","quantity":3.5,"unit":"tbsp","notes":"optional condiment layer"},{"id":"ciab-i4","section":"Finish","name":"large egg","quantity":1,"unit":"whole"},{"id":"ciab-i5","section":"Finish","name":"poppy seeds, sesame seeds, or everything bagel seasoning","quantity":0.5,"unit":"tbsp"}]', '[{"id":"ciab-s1","order":1,"instruction":"Heat the oven to 375°F and cover a large baking sheet with parchment."},{"id":"ciab-s2","order":2,"instruction":"Separate the crescent dough and cut each triangle in half so you have 16 smaller triangles."},{"id":"ciab-s3","order":3,"instruction":"Add a thin swipe of condiment to each dough piece if using, place a beef-stick half on top, then roll it up and set it on the pan with the dough end underneath."},{"id":"ciab-s4","order":4,"instruction":"Beat the egg with 1 tablespoon water, brush the wrapped bites lightly, and sprinkle with the seeds or seasoning."},{"id":"ciab-s5","order":5,"instruction":"Bake for 16 to 18 minutes, until puffed and deeply golden. Cool for about 5 minutes before serving."}]', '["Use a light hand with sweet or spicy condiments so the dough still seals easily.","Set the wrapped bites a couple inches apart so the crescent dough can puff.","Serve with extra BBQ sauce, mustard, or pepper jelly for dipping."]', '{"calories":306,"protein":"13.5 g","fat":"16.7 g","carbohydrates":"27 g"}', '["brisket-deviled-eggs","beef-brisket-taquitos"]', 'Try alternating sesame seasoning and everything bagel seasoning for a mixed party tray.', 'Refrigerate leftovers in an airtight container for up to 3 days. Reheat in an oven or air fryer to crisp the dough.', 20, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('brisket-deviled-eggs', 'Brisket Deviled Eggs', 'Classic deviled eggs folded with chopped smoked brisket and jalapeno, then finished with paprika and extra brisket.', 'Appetizer', 'Texas BBQ', 'Easy', 'images/recipes/brisket-deviled-eggs-1200.webp', 'images/recipes/brisket-deviled-eggs-640.webp', 'Deviled eggs topped with chopped smoked brisket and paprika', 'Image via Beef Loving Texans', 'https://beeflovingtexans.com/recipe/brisket-deviled-eggs/', 'Deviled eggs are a staple picnic and holiday appetizer; this version turns leftover smoked brisket into the savory accent.', 6, '12 deviled egg halves', 25, 0, 25, NULL, NULL, '["Appetizer","BBQ","Brunch","Quick & easy","Tailgating"]', '["Mixing bowl","Spoon or piping bag","Knife","Serving tray"]', '[{"id":"bde-i1","section":"Filling","name":"cooked smoked beef brisket","quantity":0.5,"unit":"cup","notes":"chopped, divided"},{"id":"bde-i2","section":"Eggs","name":"hard-boiled eggs","quantity":6,"unit":"whole","notes":"peeled and halved"},{"id":"bde-i3","section":"Filling","name":"reduced-fat mayonnaise","quantity":0.25,"unit":"cup"},{"id":"bde-i4","section":"Filling","name":"yellow mustard","quantity":1,"unit":"tbsp"},{"id":"bde-i5","section":"Filling","name":"water","quantity":1,"unit":"tsp"},{"id":"bde-i6","section":"Filling","name":"garlic salt","quantity":0.125,"unit":"tsp"},{"id":"bde-i7","section":"Filling","name":"jalapeno pepper","quantity":1,"unit":"whole","notes":"seeded and chopped"},{"id":"bde-i8","section":"Finish","name":"smoked paprika","quantity":0.5,"unit":"tsp"}]', '[{"id":"bde-s1","order":1,"instruction":"Set aside 2 tablespoons of the chopped brisket for garnish."},{"id":"bde-s2","order":2,"instruction":"Remove the yolks from the egg halves and mash them with mayonnaise, mustard, water, and garlic salt until smooth."},{"id":"bde-s3","order":3,"instruction":"Fold in the remaining chopped brisket and jalapeno."},{"id":"bde-s4","order":4,"instruction":"Spoon or pipe the filling into the egg whites, then top with the reserved brisket and a dusting of smoked paprika."},{"id":"bde-s5","order":5,"instruction":"Cover and chill until ready to serve."}]', '["Pickled red onion or pickle relish makes a bright garnish.","Use finely chopped brisket so the filling stays easy to spoon or pipe.","For less heat, use half the jalapeno or swap in a mild green chile."]', '{"calories":142,"protein":"10 g","fat":"10.5 g","carbohydrates":"2 g"}', '["cows-in-a-blanket","beef-brisket-taquitos"]', 'Try adding a few drops of hot sauce to the yolk mixture for more BBQ-joint energy.', 'Keep covered and refrigerated. Best served the same day, but leftovers can hold for 1 to 2 days.', 30, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('beef-brisket-taquitos', 'Beef Brisket Taquitos', 'Crispy air-fryer taquitos stuffed with smoked brisket, caramelized onion, pepper Jack, cream cheese, salsa, and green onion.', 'Appetizer', 'Tex-Mex', 'Easy', 'images/recipes/beef-brisket-taquitos-1200.webp', 'images/recipes/beef-brisket-taquitos-640.webp', 'Crispy beef brisket taquitos with avocado crema', 'Image via Beef Loving Texans', 'https://beeflovingtexans.com/recipe/beef-brisket-taquitos/', 'Taquitos are a compact way to turn leftover smoked brisket into a crisp snack, lunch, or party platter.', 12, '12 taquitos', 20, 10, 30, NULL, NULL, '["Air fryer","Appetizer","Quick & easy","Kid friendly","Tex-Mex"]', '["Large skillet","Medium bowl","Air fryer","Food processor"]', '[{"id":"bbt-i1","section":"Filling","name":"cooked smoked beef brisket","quantity":2.5,"unit":"cups","notes":"chopped"},{"id":"bbt-i2","section":"Filling","name":"butter","quantity":2,"unit":"tbsp"},{"id":"bbt-i3","section":"Filling","name":"thinly sliced onion","quantity":1,"unit":"cup"},{"id":"bbt-i4","section":"Filling","name":"salt","quantity":0.25,"unit":"tsp"},{"id":"bbt-i5","section":"Filling","name":"pepper Jack cheese","quantity":1,"unit":"cup","notes":"chopped"},{"id":"bbt-i6","section":"Filling","name":"cream cheese","quantity":4,"unit":"oz","notes":"softened"},{"id":"bbt-i7","section":"Filling","name":"salsa","quantity":0.5,"unit":"cup"},{"id":"bbt-i8","section":"Filling","name":"green onion","quantity":0.25,"unit":"cup","notes":"thinly sliced"},{"id":"bbt-i9","section":"Assembly","name":"corn tortillas","quantity":12,"unit":"whole","notes":"6 to 7 inch, warmed"},{"id":"bbt-i10","section":"Assembly","name":"nonstick cooking spray","quantity":1,"unit":"as needed"},{"id":"bbt-i11","section":"Avocado crema","name":"avocado","quantity":1,"unit":"whole","notes":"pitted and halved"},{"id":"bbt-i12","section":"Avocado crema","name":"jalapeno pepper","quantity":1,"unit":"whole","notes":"halved and seeded"},{"id":"bbt-i13","section":"Avocado crema","name":"fresh cilantro","quantity":0.5,"unit":"bunch"},{"id":"bbt-i14","section":"Avocado crema","name":"plain Greek-style yogurt","quantity":0.33,"unit":"cup"},{"id":"bbt-i15","section":"Avocado crema","name":"limes","quantity":2,"unit":"whole","notes":"juiced"},{"id":"bbt-i16","section":"Avocado crema","name":"salt","quantity":1,"unit":"tsp"}]', '[{"id":"bbt-s1","order":1,"instruction":"Melt the butter in a skillet over medium heat, add the onion and salt, and cook until the onion is browned and soft, about 8 to 10 minutes."},{"id":"bbt-s2","order":2,"instruction":"Mix pepper Jack, cream cheese, salsa, and green onion in a bowl. Stir in the caramelized onion and chopped brisket, then heat the air fryer to 400°F."},{"id":"bbt-s3","order":3,"instruction":"Lay out the warmed tortillas, mist both sides with cooking spray, divide the brisket filling among them, and roll each tortilla tightly."},{"id":"bbt-s4","order":4,"instruction":"Place taquitos seam-side down in one layer in the air fryer basket and cook 8 to 10 minutes, until crisp and browned."},{"id":"bbt-s5","order":5,"instruction":"Blend avocado, jalapeno, cilantro, yogurt, lime juice, and salt until smooth. Serve the crema with the hot taquitos."}]', '["Briefly crisping tortillas in a skillet can make them easier to roll without cracking.","Corn, diced potatoes, or black beans can stretch the filling.","Do not crowd the air fryer basket; cook in batches if needed."]', '{"calories":257,"protein":"12.5 g","fat":"16.5 g","carbohydrates":"16 g"}', '["brisket-deviled-eggs","barbacoa-empanadas"]', 'Try adding charred corn to the filling and serving with pico de gallo.', 'Refrigerate cooked taquitos for up to 3 days. Reheat in the air fryer to restore crispness.', 40, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('barbacoa-empanadas', 'Barbacoa Empanadas', 'Shortcut empanadas filled with prepared beef barbacoa and cheddar, baked until the pastry is golden.', 'Appetizer', 'Mexican-inspired', 'Easy', 'images/recipes/barbacoa-empanadas-1200.webp', 'images/recipes/barbacoa-empanadas-640.webp', 'Golden barbacoa empanadas with dipping sauces', 'Image via Beef Loving Texans', 'https://beeflovingtexans.com/recipe/barbacoa-empanadas/', 'Empanadas are portable filled pastries; this version uses prepared barbacoa for a fast family dinner or party appetizer.', 12, '12 empanadas', 10, 20, 30, NULL, 400, '["Appetizer","Family dinner","Mexican","Quick & easy","Texas favorites"]', '["Cookie sheet","Parchment paper","Fork","Pastry brush"]', '[{"id":"be-i1","section":"Filling","name":"prepared beef barbacoa","quantity":1.5,"unit":"cups","notes":"cooled"},{"id":"be-i2","section":"Dough","name":"frozen empanada dough shells","quantity":1,"unit":"box"},{"id":"be-i3","section":"Filling","name":"shredded cheddar cheese","quantity":1,"unit":"cup"},{"id":"be-i4","section":"Finish","name":"egg","quantity":1,"unit":"whole","notes":"beaten"}]', '[{"id":"be-s1","order":1,"instruction":"Heat the oven to 400°F and line a cookie sheet with parchment."},{"id":"be-s2","order":2,"instruction":"Place one dough round on the work surface and add a heaping spoonful each of barbacoa and shredded cheddar."},{"id":"be-s3","order":3,"instruction":"Moisten the edge if needed, fold the dough over the filling, press to seal, and crimp the edge with a fork or your fingertips."},{"id":"be-s4","order":4,"instruction":"Move the empanada to the prepared sheet and repeat with the remaining dough, beef, and cheese."},{"id":"be-s5","order":5,"instruction":"Brush the tops with beaten egg and bake 15 to 20 minutes, until golden brown."},{"id":"be-s6","order":6,"instruction":"Serve warm with salsa, guacamole, sour cream, or pico de gallo."}]', '["Keep the filling cooled so the dough stays easy to handle.","Avoid overfilling; a tight seal matters more than a stuffed pocket.","A pinch of cumin on top after the egg wash adds a little extra warmth."]', '{"calories":230,"protein":"10.8 g","fat":"15 g","carbohydrates":"14.5 g"}', '["beef-brisket-taquitos","cows-in-a-blanket"]', 'Try pepper Jack instead of cheddar or add pickled jalapenos for a sharper filling.', 'Refrigerate baked empanadas for up to 3 days. Reheat in an oven or air fryer until the pastry is warm and crisp.', 50, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('easy-lasagna-rolls', 'Easy Lasagna Rolls', 'Microwave-friendly lasagna rolls filled with cottage cheese, mozzarella, parmesan, eggs, and parsley, then covered with spaghetti sauce and more cheese.', 'Dinner', 'Italian-American', 'Easy', 'https://img.sndimg.com/food/image/upload/f_auto%2Cc_thumb%2Cq_55%2Cw_744%2Car_5%3A4/v1/img/recipes/13/10/58/7ox4GDe3RH6G6jYCA4Et_0S9A4916.jpg', 'https://img.sndimg.com/food/image/upload/f_auto%2Cc_thumb%2Cq_55%2Cw_640%2Car_16%3A9/v1/img/recipes/13/10/58/7ox4GDe3RH6G6jYCA4Et_0S9A4916.jpg', 'Lasagna rolls covered with tomato sauce, melted mozzarella, and parsley', 'Photo by Jonathan Melendez via Food.com', 'https://www.food.com/recipe/easy-lasagna-rolls-131058', 'Adapted from a Food.com community recipe submitted by Charmie777 as a quick, meatless microwave dinner that kids can help assemble.', 6, '12 lasagna rolls', 10, 20, 30, 'Microwave', NULL, '["Microwave","Meatless","Kid friendly","Quick & easy","Pasta"]', '["Microwave-safe baking dish","Mixing bowl","Spoon or spatula","Microwave-safe wrap"]', '[{"id":"elr-i1","section":"Pasta","name":"lasagna noodles","quantity":12,"unit":"whole","notes":"cooked and drained"},{"id":"elr-i2","section":"Filling","name":"cottage cheese or ricotta cheese","quantity":2,"unit":"cups"},{"id":"elr-i3","section":"Filling","name":"shredded mozzarella cheese","quantity":1.5,"unit":"cups"},{"id":"elr-i4","section":"Filling","name":"parmesan cheese","quantity":0.5,"unit":"cup"},{"id":"elr-i5","section":"Filling","name":"eggs","quantity":2,"unit":""},{"id":"elr-i6","section":"Filling","name":"chopped parsley","quantity":2,"unit":"tbsp"},{"id":"elr-i7","section":"Sauce","name":"spaghetti sauce","quantity":32,"unit":"oz jar"},{"id":"elr-i8","section":"Finish","name":"shredded mozzarella cheese","quantity":1.5,"unit":"cups","notes":"use 1 to 2 cups for topping"}]', '[{"id":"elr-s1","order":1,"instruction":"Stir the cottage cheese or ricotta with 1 1/2 cups mozzarella, parmesan, eggs, and parsley until evenly combined."},{"id":"elr-s2","order":2,"instruction":"Spread about 2 cups spaghetti sauce across the bottom of a microwave-safe baking dish."},{"id":"elr-s3","order":3,"instruction":"Lay out one cooked noodle, spread about 1/3 cup cheese filling over it, then roll it up snugly."},{"id":"elr-s4","order":4,"instruction":"Set each roll seam-side down in the sauced dish and repeat with the remaining noodles and filling."},{"id":"elr-s5","order":5,"instruction":"Spoon the rest of the sauce over the rolls, add the topping mozzarella, and cover with microwave-safe wrap."},{"id":"elr-s6","order":6,"instruction":"Microwave on high until the rolls are hot and the cheese is melted, about 10 to 20 minutes depending on the dish and microwave."}]', '["Use cooked noodles that are flexible but not falling apart so they roll cleanly.","Leave a little space at the end of each noodle to keep the filling from pushing out as you roll.","For an oven version, bake covered until hot, then uncover briefly to melt and brown the cheese."]', '{"calories":509,"protein":"30.9 g","fat":"182 g","carbohydrates":"49.2 g"}', '["barbacoa-empanadas","cows-in-a-blanket"]', 'Try adding spinach, browned Italian sausage, or extra herbs to the cheese filling.', 'Refrigerate leftovers in an airtight container for up to 4 days. Reheat individual rolls in the microwave with extra sauce.', 60, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('chicken-rice-casserole', 'Chicken & Rice Casserole', 'Creamy one-dish chicken and rice with broccoli and cheddar. Makes great leftovers.', 'Dinner', 'Southern comfort food', 'Easy', NULL, NULL, 'Chicken & Rice Casserole recipe', 'Next Thyme placeholder', '#', '', 6, 'One 9x13 casserole', 15, 65, 80, 'Oven', 375, '["Southern","Leftover-friendly","Family dinner"]', '["9x13 baking dish","Foil","Instant-read thermometer"]', '[{"id":"crc-i1","section":"Casserole","name":"boneless skinless chicken thighs","quantity":2.5,"unit":"lb"},{"id":"crc-i2","section":"Casserole","name":"long-grain white rice","quantity":1,"unit":"cup","notes":"uncooked"},{"id":"crc-i3","section":"Casserole","name":"cream of chicken soup","quantity":2,"unit":"cans","notes":"10.5 oz each"},{"id":"crc-i4","section":"Casserole","name":"chicken broth","quantity":1.5,"unit":"cups"},{"id":"crc-i5","section":"Casserole","name":"yellow onion","quantity":0.5,"unit":"whole","notes":"diced"},{"id":"crc-i6","section":"Casserole","name":"garlic powder","quantity":1,"unit":"tsp"},{"id":"crc-i7","section":"Casserole","name":"salt","quantity":0.5,"unit":"tsp"},{"id":"crc-i8","section":"Casserole","name":"black pepper","quantity":0.5,"unit":"tsp"},{"id":"crc-i9","section":"Topping","name":"frozen broccoli florets","quantity":12,"unit":"oz","notes":"thawed"},{"id":"crc-i10","section":"Topping","name":"shredded sharp cheddar","quantity":1,"unit":"cup"},{"id":"crc-i11","section":"Baking dish","name":"butter","quantity":1,"unit":"tbsp","notes":"for the dish"}]', '[{"id":"crc-s1","order":1,"instruction":"Preheat oven to 375°F. Butter a 9x13 baking dish."},{"id":"crc-s2","order":2,"instruction":"In the dish, stir together the soup, broth, rice, onion, garlic powder, salt, and pepper. Spread evenly."},{"id":"crc-s3","order":3,"instruction":"Lay the chicken thighs on top and season lightly with salt and pepper."},{"id":"crc-s4","order":4,"instruction":"Cover tightly with foil and bake 50 minutes."},{"id":"crc-s5","order":5,"instruction":"Uncover, tuck the broccoli around the chicken, and sprinkle with cheddar. Bake uncovered 15 more minutes, until the rice is tender and the chicken reaches 175°F."},{"id":"crc-s6","order":6,"instruction":"Rest 10 minutes before serving."}]', '["It is done when the rice is tender and the chicken reaches 175°F.","Rest the casserole 10 minutes before serving.","Makes great leftovers."]', '{"calories":0,"protein":"Not added","fat":"Not added","carbohydrates":"Not added"}', '["creamy-smoked-sausage-tortellini","meatloaf-mashed-potatoes-green-beans"]', 'Add a note after you make it once.', 'Store leftovers in an airtight container in the refrigerator.', 70, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('creamy-smoked-sausage-tortellini', 'Creamy Smoked Sausage Tortellini', 'One-pan cheese tortellini in a creamy parmesan sauce with smoked sausage. Ready in about 25 minutes.', 'Dinner', 'Southern comfort food', 'Easy', NULL, NULL, 'Creamy Smoked Sausage Tortellini recipe', 'Next Thyme placeholder', '#', '', 5, '5 servings', 5, 20, 25, 'Stovetop', NULL, '["Southern","Leftover-friendly","Family dinner","Quick & easy","Pasta"]', '["Large deep skillet with lid","Spoon or spatula"]', '[{"id":"sst-i1","section":"Sausage","name":"smoked sausage","quantity":14,"unit":"oz","notes":"sliced into coins"},{"id":"sst-i2","section":"Sausage","name":"butter","quantity":1,"unit":"tbsp"},{"id":"sst-i3","section":"Sausage","name":"yellow onion","quantity":0.5,"unit":"whole","notes":"diced"},{"id":"sst-i4","section":"Sausage","name":"garlic","quantity":3,"unit":"cloves","notes":"minced"},{"id":"sst-i5","section":"Sauce and pasta","name":"chicken broth","quantity":1.5,"unit":"cups"},{"id":"sst-i6","section":"Sauce and pasta","name":"milk","quantity":1,"unit":"cup"},{"id":"sst-i7","section":"Sauce and pasta","name":"frozen cheese tortellini","quantity":19,"unit":"oz"},{"id":"sst-i8","section":"Sauce and pasta","name":"cream cheese","quantity":4,"unit":"oz","notes":"cubed"},{"id":"sst-i9","section":"Sauce and pasta","name":"grated parmesan","quantity":0.5,"unit":"cup"},{"id":"sst-i10","section":"Finish","name":"fresh spinach","quantity":2,"unit":"cups","notes":"optional"},{"id":"sst-i11","section":"Finish","name":"salt and pepper","quantity":1,"unit":"to taste"}]', '[{"id":"sst-s1","order":1,"instruction":"In a large deep skillet over medium-high heat, brown the sausage in the butter, about 5 minutes."},{"id":"sst-s2","order":2,"instruction":"Add the onion and cook 3 minutes, then add the garlic for 30 seconds."},{"id":"sst-s3","order":3,"instruction":"Pour in the broth and milk and bring to a simmer."},{"id":"sst-s4","order":4,"instruction":"Stir in the tortellini, cover, and simmer 6–8 minutes, stirring once or twice, until tender."},{"id":"sst-s5","order":5,"instruction":"Stir in the cream cheese and parmesan until the sauce is smooth. Add the spinach, if using, and stir until wilted."},{"id":"sst-s6","order":6,"instruction":"Season with salt and pepper. Let stand 2 minutes to thicken."}]', '["Everything cooks in one pan, in about 25 minutes.","The spinach is optional. Stir it in at the end, just until wilted.","Let the skillet stand 2 minutes off the heat so the sauce thickens."]', '{"calories":0,"protein":"Not added","fat":"Not added","carbohydrates":"Not added"}', '["chicken-rice-casserole","easy-lasagna-rolls"]', 'Add a note after you make it once.', 'Store leftovers in an airtight container in the refrigerator.', 80, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('slow-cooker-pot-roast', 'Slow Cooker Pot Roast', 'Classic fall-apart chuck roast with potatoes and carrots. Leftovers make great roast beef sandwiches.', 'Dinner', 'Southern comfort food', 'Easy', NULL, NULL, 'Slow Cooker Pot Roast recipe', 'Next Thyme placeholder', '#', '', 6, 'One 3 lb roast', 15, 480, 495, 'Slow cooker', NULL, '["Southern","Leftover-friendly","Family dinner"]', '["Slow cooker","Large skillet"]', '[{"id":"scpr-i1","section":"Roast","name":"beef chuck roast","quantity":3,"unit":"lb"},{"id":"scpr-i2","section":"Roast","name":"oil","quantity":1,"unit":"tbsp","notes":"for the optional sear"},{"id":"scpr-i3","section":"Roast","name":"onion soup mix","quantity":1,"unit":"packet","notes":"2 oz"},{"id":"scpr-i4","section":"Roast","name":"beef broth","quantity":2,"unit":"cups"},{"id":"scpr-i5","section":"Vegetables","name":"russet potatoes","quantity":1.5,"unit":"lb","notes":"cut into large chunks"},{"id":"scpr-i6","section":"Vegetables","name":"carrots","quantity":1,"unit":"lb","notes":"peeled and cut into 2-inch pieces"},{"id":"scpr-i7","section":"Vegetables","name":"yellow onion","quantity":1,"unit":"whole","notes":"cut into wedges"},{"id":"scpr-i8","section":"Vegetables","name":"garlic","quantity":3,"unit":"cloves","notes":"smashed"},{"id":"scpr-i9","section":"Roast","name":"salt and pepper","quantity":1,"unit":"to taste"}]', '[{"id":"scpr-s1","order":1,"instruction":"Pat the roast dry and season with salt and pepper. Optional: sear in oil in a hot skillet, 3–4 minutes per side."},{"id":"scpr-s2","order":2,"instruction":"Put the potatoes, carrots, onion, and garlic in the slow cooker."},{"id":"scpr-s3","order":3,"instruction":"Set the roast on top of the vegetables, sprinkle with the onion soup mix, and pour the broth around it."},{"id":"scpr-s4","order":4,"instruction":"Cover and cook on low 8–9 hours or high 5–6 hours, until the beef shreds easily."},{"id":"scpr-s5","order":5,"instruction":"Break into large pieces and serve with the vegetables and cooking juices spooned over."}]', '["Cook on low for 8–9 hours, or on high for 5–6 hours.","Searing the roast first is optional: 3–4 minutes per side in a hot skillet.","It is done when the beef shreds easily."]', '{"calories":0,"protein":"Not added","fat":"Not added","carbohydrates":"Not added"}', '["pot-roast","meatloaf-mashed-potatoes-green-beans"]', 'Add a note after you make it once.', 'Store leftovers in an airtight container in the refrigerator. Leftovers make great roast beef sandwiches.', 90, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;

INSERT INTO recipes (id, title, description, category, cuisine, difficulty, image_url, image_small_url, image_alt, image_credit, image_credit_url, history, servings, yield_label, prep_time_minutes, cook_time_minutes, total_time_minutes, cooking_method, oven_temp_f, tags, equipment, ingredients, directions, tips, nutrition, similar_recipe_ids, next_time_notes, leftover_storage, sort_order, created_at, updated_at)
VALUES ('meatloaf-mashed-potatoes-green-beans', 'Meatloaf with Mashed Potatoes & Green Beans', 'Ketchup-glazed meatloaf with buttery mashed potatoes and green beans. Leftovers make great cold meatloaf sandwiches.', 'Dinner', 'Southern comfort food', 'Easy', NULL, NULL, 'Meatloaf with Mashed Potatoes & Green Beans recipe', 'Next Thyme placeholder', '#', '', 6, 'One 9x5 loaf', 20, 70, 90, 'Oven', 350, '["Southern","Leftover-friendly","Family dinner"]', '["Large bowl","Sheet pan","Foil","Large pot","Potato masher","Saucepan","Instant-read thermometer"]', '[{"id":"mlf-i1","section":"Meatloaf","name":"ground beef","quantity":2,"unit":"lb","notes":"80/20"},{"id":"mlf-i2","section":"Meatloaf","name":"crushed saltine crackers","quantity":1,"unit":"cup","notes":"about 25 crackers"},{"id":"mlf-i3","section":"Meatloaf","name":"milk","quantity":0.5,"unit":"cup"},{"id":"mlf-i4","section":"Meatloaf","name":"eggs","quantity":2,"unit":""},{"id":"mlf-i5","section":"Meatloaf","name":"small onion","quantity":1,"unit":"whole","notes":"finely diced"},{"id":"mlf-i6","section":"Meatloaf","name":"garlic powder","quantity":1,"unit":"tsp"},{"id":"mlf-i7","section":"Meatloaf","name":"salt","quantity":1,"unit":"tsp"},{"id":"mlf-i8","section":"Meatloaf","name":"black pepper","quantity":0.5,"unit":"tsp"},{"id":"mlf-i9","section":"Glaze","name":"ketchup","quantity":0.5,"unit":"cup"},{"id":"mlf-i10","section":"Glaze","name":"brown sugar","quantity":2,"unit":"tbsp"},{"id":"mlf-i11","section":"Mashed potatoes","name":"russet potatoes","quantity":2.5,"unit":"lb","notes":"peeled and cubed"},{"id":"mlf-i12","section":"Mashed potatoes","name":"butter","quantity":4,"unit":"tbsp"},{"id":"mlf-i13","section":"Mashed potatoes","name":"milk","quantity":0.5,"unit":"cup","notes":"warmed"},{"id":"mlf-i14","section":"Mashed potatoes","name":"salt","quantity":1,"unit":"to taste"},{"id":"mlf-i15","section":"Green beans","name":"cut green beans","quantity":2,"unit":"cans","notes":"14.5 oz each, drained"},{"id":"mlf-i16","section":"Green beans","name":"butter","quantity":1,"unit":"tbsp"},{"id":"mlf-i17","section":"Green beans","name":"garlic powder","quantity":0.25,"unit":"tsp"},{"id":"mlf-i18","section":"Green beans","name":"salt and pepper","quantity":1,"unit":"to taste"}]', '[{"id":"mlf-s1","order":1,"instruction":"Preheat oven to 350°F."},{"id":"mlf-s2","order":2,"instruction":"In a large bowl, soak the crushed crackers in the milk for 2 minutes. Add the eggs, onion, garlic powder, salt, pepper, and ground beef, and mix gently with your hands until just combined."},{"id":"mlf-s3","order":3,"instruction":"Shape into a loaf about 9x5 inches on a foil-lined sheet pan."},{"id":"mlf-s4","order":4,"instruction":"Stir together the ketchup and brown sugar and spread half over the loaf. Bake 45 minutes."},{"id":"mlf-s5","order":5,"instruction":"Spread on the remaining glaze and bake 15–25 more minutes, until the center reaches 160°F. Rest 10 minutes before slicing."},{"id":"mlf-s6","order":6,"instruction":"Meanwhile, cover the potatoes with cold salted water, bring to a boil, and cook 15–18 minutes until fork-tender. Drain, then mash with the butter and warm milk. Season with salt."},{"id":"mlf-s7","order":7,"instruction":"Heat the green beans with the butter and garlic powder over medium heat for 5 minutes. Season with salt and pepper."}]', '["Mix the meat gently, only until just combined.","The meatloaf is done when the center reaches 160°F.","Rest it 10 minutes before slicing."]', '{"calories":0,"protein":"Not added","fat":"Not added","carbohydrates":"Not added"}', '["slow-cooker-pot-roast","chicken-rice-casserole"]', 'Add a note after you make it once.', 'Store leftovers in an airtight container in the refrigerator. Leftovers make great cold meatloaf sandwiches.', 100, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE id = id;
